import csv
from datetime import datetime
from collections import defaultdict
from decimal import Decimal
# load catalog
catalog={}
ean_map={}
with open('dataset/product_catalog.csv', newline='') as f:
    for r in csv.DictReader(f):
        catalog[r['product_id']]={
            'name': r['name'],
            'category': r['storage_category'],
            'price': Decimal(r['unit_price'].replace(',','.').replace('"','')),
            'safe': float(r['max_safe_temp_c']),
        }
        ean_map[r['ean_code']]=r['product_id']
# breach intervals
by_zone=defaultdict(list)
with open('dataset/temperature_logs.csv', newline='') as f:
    for r in csv.DictReader(f):
        zone=r['zone'].strip().lower()
        ts=datetime.fromisoformat(r['timestamp'])
        temp=float(r['temperature_c'].replace(',','.'))
        by_zone[zone].append((ts,temp))
for v in by_zone.values():
    v.sort()
# safe by normalized zone from catalog categories
safe_by_zone={'frozen':-10.0,'meat':4.0,'dairy':6.0,'dry':35.0}
intervals=[]
for zone, readings in by_zone.items():
    safe=safe_by_zone[zone]
    for i,(ts,temp) in enumerate(readings[:-1]):
        next_ts=readings[i+1][0]
        if temp>safe:
            intervals.append((zone,ts,next_ts))
# load/dedupe dispatches
rows=[]
seen=set()
with open('dataset/warehouse_dispatches.csv', newline='') as f:
    for r in csv.DictReader(f):
        pid=r['product_id']
        if pid not in catalog:
            pid=ean_map[pid]
        key=(r['timestamp'],pid,r['quantity'],r['total_weight_kg'])
        if key in seen:
            continue
        seen.add(key)
        rows.append({
            'dispatch_id': int(r['dispatch_id']),
            'timestamp': datetime.fromisoformat(r['timestamp']),
            'timestamp_str': r['timestamp'],
            'product_id': pid,
            'qty': int(r['quantity']),
            'category': catalog[pid]['category'],
            'name': catalog[pid]['name'],
            'price': catalog[pid]['price'],
        })
# flag dispatches whose category was in a breached zone at that timestamp
breached_by_ts=defaultdict(set)
for r in rows:
    zone=r['category'].lower()
    for z,start,end in intervals:
        if z==zone and start <= r['timestamp'] < end:
            breached_by_ts[r['timestamp_str']].add(zone)
# group by timestamp
groups=defaultdict(list)
for r in rows:
    groups[r['timestamp_str']].append(r)
for ts, grp in sorted(groups.items()):
    cats={r['category'].lower() for r in grp}
    if breached_by_ts.get(ts):
        print(ts, 'group_size', len(grp), 'cats', cats, 'breached', breached_by_ts[ts], 'value', int(sum(r['price']*r['qty'] for r in grp)))
        for r in grp:
            print(' ', r['dispatch_id'], r['category'], r['name'], r['qty'])
